-- CozyHealth shared food library (cozyhealth.generic_meals).
--
-- This is the seed data behind the Food tab's contextual suggestions and
-- search. It is version controlled here so the curated nutrition values are
-- not stored only inside applied migrations.
--
-- Generated from the live table rather than hand-written, so it reflects what
-- the app actually reads. Re-runnable: `on conflict do nothing` leaves any
-- existing row alone.
--
-- Values are per the portion named. Whole foods use standard reference data;
-- packaged products use label values. Micros left at 0 are negligible or not
-- printed on the label, not "unknown".
--
-- Notable entries:
--   seitan-loaf / seitan-serving  one loaf = 2 cups vital wheat gluten
--                                 + 1/2 cup nutritional yeast + 1 block tofu
--   ind-*                         the original CozyHealth single-ingredient set
--   quest-*, david-bar, premier-shake, orgain-powder, collagen, ...
--                                 diet snacks, bars, shakes and powders

insert into cozyhealth.generic_meals
    (id, name, meal_type, icon,
     animal_protein, plant_protein, saturated_fat, unsaturated_fat, whole_grains,
     vegetables, fruits, simple_carbs, fiber, alcohol,
     calories, protein_grams, carbs_grams, fat_grams, fiber_grams, sugar_grams, sodium_mg,
     vitamin_a_mcg, vitamin_c_mg, vitamin_d_mcg, calcium_mg, iron_mg, potassium_mg,
     folate_mcg, choline_mg, omega3_dha_mg, omega3_epa_mg)
